{"summary": "Implement solve as global-vs-local inversion equality check with efficient prefix-max scan.", "files": {"solution.py": """"Write a python function to check whether the count of inversion of two types are same or not."""


def solve(a, n):
    """Return True iff the number of global inversions equals the number of local inversions.

    A global inversion is a pair i < j with a[i] > a[j].
    A local inversion is an index i with a[i] > a[i+1].
    """
    if a is None:
        return True
    try:
        length = int(n)
    except (TypeError, ValueError):
        length = len(a)
    if length <= 1:
        return True
    try:
        arr = list(a[:length])
    except Exception:
        arr = list(a)[:length]
    if len(arr) <= 1:
        return True
    # Local inversions are a subset of global inversions, so the counts are
    # equal iff there is no non-local global inversion (i + 1 < j, a[i] > a[j]),
    # i.e. max(a[0..j-2]) <= a[j] for every j >= 2.
    running_max = arr[0]
    for j in range(2, len(arr)):
        if running_max > arr[j]:
            return False
        if arr[j - 1] > running_max:
            running_max = arr[j - 1]
    return True
